def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def step_toward(a, b):
        return clamp_step(b - a)

    def dist1(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    def safe_pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def pick_nearest(points, sx, sy):
        best = None
        best_d = None
        for p in points or []:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                px, py = p[0], p[1]
                d = dist1(sx, sy, px, py)
                if best is None or d < best_d:
                    best = (px, py)
                    best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pos(observation.get("self_position", (0, 0)))
    ox, oy = safe_pos(observation.get("opponent_position", (sx, sy)))

    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0
    cx = gw // 2 if gw else sx
    cy = gh // 2 if gh else sy

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            dx = step_toward(sx, ox)
            dy = step_toward(sy, oy)
            return [dx, dy]
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
            target = max(corners, key=lambda p: dist1(p[0], p[1], ox, oy))
            return [step_toward(sx, target[0]), step_toward(sy, target[1])]
        return [step_toward(ox, sx), step_toward(oy, sy)]

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier")
            or []
        )
        best = pick_nearest(targets, sx, sy)
        if best is not None:
            return [step_toward(sx, best[0]), step_toward(sy, best[1])]
        return [step_toward(sx, cx), step_toward(sy, cy)]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = pick_nearest(resources, sx, sy)
    if best is not None:
        return [step_toward(sx, best[0]), step_toward(sy, best[1])]

    # Fallback: move toward center unless opponent is closer, then create space.
    if dist1(sx, sy, ox, oy) <= 2:
        return [step_toward(ox, sx), step_toward(oy, sy)]
    return [step_toward(sx, cx), step_toward(sy, cy)]

